// Optional flattened access for templates that expect one question array.
var joaItQuestions = joaItData.flatMap(function (paper) {
  return paper.questions.map(function (q) {
    return Object.assign({ paper: paper.paper }, q);
  });
});

// Answer-key placeholder registry. Fill only from verified official answer keys.
var joaItAnswerKeys = joaItData.map(function (paper) {
  return {
    paper: paper.paper,
    answers: paper.questions.map(function (q) {
      return { number: q.number, answer: q.answer, status: q.answerStatus };
    })
  };
});


// Combined CommonJS export; original dataset identifiers are preserved.
if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    joadatajspyq: joadatajspyq,
    joaItData: joaItData,
    joaItQuestions: joaItQuestions,
    joaItAnswerKeys: joaItAnswerKeys
  };
}
